    .reg .b64 %rd<30>;
    .reg .f32 %f<40>;
    .reg .pred %p<60>;
    .shared .align 16 .f32 sharedRow[64];
    .shared .align 4 .f32 sharedWeightCache[24];
    ld.param.u64 %rd1, [param_input];
    ld.param.u64 %rd2, [param_weight];
    ld.param.u64 %rd3, [param_output];
    ld.param.u32 %r1, [param_n];
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    mov.u32 %r2, %ctaid.x;       // block index (b,oc_group,od,oh) flattened
    mov.u32 %r3, %tid.x;         // raw tid in [0, 96) ; valid range [0, 88)
