    div.u32 %r11, %r2, %r10;
    rem.u32 %r12, %r2, %r10;      // oh
    mov.u32 %r13, 66;
    div.u32 %r14, %r11, %r13;
    rem.u32 %r15, %r11, %r13;     // od
    mov.u32 %r16, 6;
    div.u32 %r17, %r14, %r16;     // b
    rem.u32 %r18, %r14, %r16;     // oc_group
