    setp.ge.s32 %p51, %r248, 64;
    mov.f32 %f34, 0f00000000;
    @%p51 bra R5_DONE;
    mad.lo.s32 %r249, %r248, 4, %r204;
    ld.shared.f32 %f34, [%r249];
