    sub.s32 %r250, %r92, 1;
    setp.lt.s32 %p52, %r250, 0;
    mov.f32 %f24, 0f00000000;
    @%p52 bra RM1_DONE;
    mad.lo.s32 %r251, %r250, 4, %r204;
    ld.shared.f32 %f24, [%r251];
